using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Threading.Tasks;using System.Windows;using System.Windows.Input;
static class V132Checks {
 static void Type(EditorInput input,string text){var c=new TextComposition(InputManager.Current,input.TextArea,text);input.TextArea.RaiseEvent(new TextCompositionEventArgs(Keyboard.PrimaryDevice,c){RoutedEvent=TextCompositionManager.TextInputEvent});}
 public static void UI(Application app,string path){Engine.DataRoot=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),"state-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Engine.DataRoot);AppSettings.Load();GlassTheme.Apply(false,false);var log=new List<string>();Action<bool,string> check=(ok,t)=>{log.Add((ok?"PASS ":"FAIL ")+t);if(!ok)throw new Exception(t);};var w=new MainWindow(true);w.ContentRendered+=async(s,e)=>{try{await Transitions.WhenReady(w);var ed=(CodeEditor)typeof(MainWindow).GetField("editor",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(w);var i=ed.Input;i.Focus();
 Action<string,int> reset=(t,p)=>{i.IsReadOnly=false;i.Text=t;i.Select(p,0);i.Document.UndoStack.ClearAll();};
 string opens="([{\"'（［｛“‘【「『",closes=")] }\"'）］｝”’】」』".Replace(" ","");
 foreach(bool dark in new[]{false,true}){if(dark)ed.SetDark();for(int n=0;n<opens.Length;n++){reset("",0);Type(i,opens[n].ToString());check(i.Text==""+opens[n]+closes[n]&&i.CaretOffset==1,"Pair and caret "+opens[n]+" dark="+dark);i.Undo();check(i.Text=="","Single undo removes pair");i.Redo();check(i.Text==""+opens[n]+closes[n],"Redo restores pair");i.Select(1,0);Type(i,closes[n].ToString());check(i.Text.Length==2&&i.CaretOffset==2,"Closer skips existing character");i.Select(1,0);i.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(w),0,Key.Back){RoutedEvent=Keyboard.PreviewKeyDownEvent});check(i.Text==""&&i.CaretOffset==0,"Routed backspace removes empty pair");i.Undo();check(i.Text==""+opens[n]+closes[n],"Undo restores deletion");}}
 reset("",0);foreach(char c in "printf(\"%d\", a[0]);")Type(i,c.ToString());check(i.Text=="printf(\"%d\", a[0]);"&&i.CaretOffset==i.Text.Length,"Real typing nested call and literal, no duplicate closers");
 reset("",0);foreach(char c in "char c = '\\'';")Type(i,c.ToString());check(i.Text=="char c = '\\'';","Escaped apostrophe remains exact");
 reset("",0);foreach(char c in "puts(\"a\\\"b\");")Type(i,c.ToString());check(i.Text=="puts(\"a\\\"b\");","Escaped double quote remains exact");
 foreach(string before in new[]{"// note ","/* note ","\"text ","'"}){reset(before,before.Length);Type(i,"(");check(i.Text==before+"(","No bracket expansion in comment or literal");}
 reset("int value",9);Type(i,"\"");check(i.Text=="int value\"","Quote adjacent to identifier is not expanded");
 reset("prefix value suffix",7);i.Select(7,5);Type(i,"(");check(i.Text=="prefix (value) suffix"&&i.SelectionStart==8&&i.SelectionLength==5,"Selection wrapped without losing text");i.Undo();check(i.Text=="prefix value suffix","Single undo restores selected source");
 reset("// note\n",8);Type(i,"{");check(i.Text=="// note\n{}","Newline ends line comment");reset("/* note */ ",11);Type(i,"(");check(i.Text=="/* note */ ()","Block comment ending restores code context");
 reset("",0);Type(i,"()");check(i.Text=="()","Multi-character committed input stays exact");reset("",0);i.SelectedText="puts(\"x\");";check(i.Text=="puts(\"x\");","Paste and imports stay exact");reset("",0);i.IsReadOnly=true;Type(i,"(");check(i.Text=="","Read-only answers cannot be modified");i.IsReadOnly=false;
 int hits=0;foreach(int font in AppSettings.FontSizes){ed.SetFontSize(font);reset("int main(void) {\n    puts(\"ok\");\n}",4);Type(i,"(");Type(i,")");w.UpdateLayout();ed.RefreshView();i.ScrollToHome();for(int p=0;p<i.Text.Length-1;p++){if(i.Text[p]=='\n'||i.Text[p+1]=='\n')continue;var a=i.CharacterRect(p);var b=i.CharacterRect(p+1);if(b.X<=a.X)continue;check(i.Hit(new Point(a.X+(b.X-a.X)*.2,a.Y+a.Height*.5))==p,"Glyph hit after completion "+font+" / "+p);hits++;}}
 reset("",0);string reference=Bank.All()[0].Reference.Replace("\r\n","\n");foreach(char c in reference)Type(i,c.ToString());check(System.Text.RegularExpressions.Regex.Replace(i.Text,@"\s+","")==System.Text.RegularExpressions.Regex.Replace(reference,@"\s+",""),"Complete C answer retains all symbols and tokens with automatic indentation");string typedCode=i.Text;var evaluation=await Task.Run(()=>Engine.Judge(Bank.All()[0],typedCode,20261120,System.Threading.CancellationToken.None,(a,b)=>{}));check(evaluation.Compiled&&evaluation.Cases.Count==28&&evaluation.Cases.All(c=>c.Passed)&&evaluation.Score>=99.9,"Typed answer compiles and passes 28 cases at 100 points");check(Bank.All().Count==150&&ChallengeBank.Levels.Count==50,"150 ordinary questions and 50 dark levels retained");log.Add("ALL VER1.3.2 PAIR CHECKS PASSED / glyph hits="+hits);File.WriteAllLines(path,log);w.Close();}catch(Exception ex){log.Add("FAIL "+ex);File.WriteAllLines(path,log);app.Shutdown(1);}};app.Run(w);}
}




